// 1. async/await maduro (12+ anos de polish)
public async IAsyncEnumerable<Pedido> StreamPedidosAsync(
    [EnumeratorCancellation] CancellationToken ct) {
    await foreach (var row in db.Query(ct).ConfigureAwait(false)) {
        yield return Map(row);
    }
}

